            int ys0 = -1, ys1 = -1, xa = -1, xb = -1;
            for (int y = y0 + 1; y < y0 + CELL_H; y += 2) if (y >= BORDER && y < IMG_H - BORDER) { if (ys0 < 0) ys0 = y; ys1 = y; }
